import sys; sys.path.insert(0,'/tmp')
exec(open('/tmp/load.py').read())
from lp import *
smin={s:(Fr(suites[s]['random_guess']) if suites[s]['scoring']=='raw' else Fr(0)) for s in suites}
def F(x): return Fr(str(x))
def bounds(r):
    s=plan[r][0]; st=states[r]
    if 'value' in st: v=F(ev[r]); return (v,v)
    if 'scraped' in st: v=F(rec[r])/100; return (v,v)
    if 'below_retention_floor' in st: return (smin[s], F(floor_at(ts(rt[r])))-F('0.0001'))
    if 'shard_file_lost' in st: return (F(floor_at(ts(rt[r]))), Fr(1))
    return (smin[s],Fr(1))
B={r:bounds(r) for r in launch}
byday=collections.defaultdict(list)
for r in launch: byday[rt[r][:10]].append(r)
unk={d:[r for r in rs if B[r][0]!=B[r][1]] for d,rs in byday.items()}
Rd={}
for d in byday:
    Rd[d]=F(digest[d][1])-sum(B[r][0] for r in byday[d] if B[r][0]==B[r][1])
RW={'arc_lite':F('0.04'),'gsm_plus':F('0.02'),'code_ms':F('0.025')}
def outcome(r):
    st=states[r]
    if 'value' in st or 'scraped' in st: return None
    if 'shard_file_lost' in st: return Fr(0)
    if 'below_retention_floor' in st: return RW[plan[r][0]]
    return None  # inc4471 / inc4530: unknown -> worst case nothing
def groups(cfg):
    key=(cfg['suite'],cfg['curriculum'],cfg['retrieval'],cfg['decoder'])
    return [r for r in launch if plan[r]==key]
def coefs(fr,to):
    T=groups(to); Fm=groups(fr); c={}
    for r in T: c[r]=c.get(r,0)+Fr(1,len(T))
    for r in Fm: c[r]=c.get(r,0)-Fr(1,len(Fm))
    return c
def day_vars(d,c,coupled):
    """aggregate zero-coef uncoupled unknowns"""
    vs=[]; agg_l=Fr(0); agg_u=Fr(0); agg=False
    for r in unk[d]:
        if c.get(r,0)==0 and r not in coupled:
            agg=True; agg_l+=B[r][0]; agg_u+=B[r][1]
        else: vs.append((r,B[r][0],B[r][1],c.get(r,0),coupled.get(r)))
    if agg: vs.append(('_agg',agg_l,agg_u,Fr(0),None))
    return vs
def day_lp(d,c,coupled,mode):
    """mode 'width': max sum c(x-y) with couplings; 'max'/'min': extreme of sum c x."""
    vs=day_vars(d,c,coupled)
    n=len(vs)
    if n==0: return Fr(0)
    if mode=='width':
        nv=2*n
        obj=[v[3] for v in vs]+[-v[3] for v in vs]
        A_ub=[];b_ub=[]
        for k,v in enumerate(vs):
            for off in (0,n):
                row=[Fr(0)]*nv; row[k+off]=Fr(1); A_ub.append(row); b_ub.append(v[2]-v[1])
            if v[4] is not None:
                row=[Fr(0)]*nv; row[k]=Fr(1); row[k+n]=Fr(-1); A_ub.append(row); b_ub.append(v[4])
                row=[Fr(0)]*nv; row[k]=Fr(-1); row[k+n]=Fr(1); A_ub.append(row); b_ub.append(v[4])
        A_eq=[[Fr(1)]*n+[Fr(0)]*n,[Fr(0)]*n+[Fr(1)]*n]
        beq=Rd[d]-sum(v[1] for v in vs)
        val,_=simplex_max(obj,A_ub,b_ub,A_eq,[beq,beq])
        return val
    else:
        sgn=1 if mode=='max' else -1
        obj=[sgn*v[3] for v in vs]
        A_ub=[];b_ub=[]
        for k,v in enumerate(vs):
            row=[Fr(0)]*n; row[k]=Fr(1); A_ub.append(row); b_ub.append(v[2]-v[1])
        beq=Rd[d]-sum(v[1] for v in vs)
        val,_=simplex_max(obj,A_ub,b_ub,[[Fr(1)]*n],[beq])
        return sgn*val+sum(v[3]*v[1] for v in vs)
def relevant_days(c):
    return sorted({rt[r][:10] for r in c if B[r][0]!=B[r][1]})
def interval(fr,to):
    c=coefs(fr,to)
    const=sum(c[r]*B[r][0] for r in c if B[r][0]==B[r][1])
    lo=const; hi=const
    for d in relevant_days(c):
        lo+=day_lp(d,c,{},'min'); hi+=day_lp(d,c,{},'max')
    return lo,hi
def gwidth(fr,to,S):
    c=coefs(fr,to)
    coupled={r:outcome(r) for r in S if outcome(r) is not None}
    days=set(relevant_days(c))|{rt[r][:10] for r in coupled}
    tot=Fr(0)
    for d in sorted(days):
        tot+=day_lp(d,c,{r:w for r,w in coupled.items() if rt[r][:10]==d},'width')
    return tot
